/**
 * @license
 * Sunshine Brigade Worksheet Builder - Picture tags
 *
 * One line of facts for every drawn picture, so every block can use the whole library:
 *   t  theme (the redraw file it came from)
 *   k  kind: animal, fruit, veg, food, nature, home, clothes, toy, vehicle, farm
 *   s  syllables when you clap it (0 = people say it more than one way: left out of clapping)
 *   z  real-life size: 1 tiny (ant) .. 5 huge (elephant, house)
 *   m  how it moves: land, water or air (animals and vehicles)
 * Rhyme families, trips (who goes where) and go-together pairs are listed below the table.
 * LOOKALIKES: pairs whose shadows overlap by over 75% in the template frame, so the
 * shadow puzzles never ask a child to tell them apart.
 *
 * Generated from the redraw files and reviewed by hand: add new pictures here as they arrive.
 */

export type PictureTheme = 'farm' | 'wild' | 'woodland' | 'ocean' | 'garden' | 'food' | 'home' | 'clothes' | 'toys' | 'go';
export type PictureKind = 'animal' | 'fruit' | 'veg' | 'food' | 'nature' | 'home' | 'clothes' | 'toy' | 'vehicle' | 'farm';
export type Moves = 'land' | 'water' | 'air';

export interface PictureTag { t: PictureTheme; k: PictureKind; s: number; z: number; m?: Moves }

